mapper.sql:
DELETED = 0

    AND TASK_ID = #{q.taskId}


    AND TASK_ID IN (
        SELECT DISTINCT DEVICE_FILTER.TASK_ID
        FROM T_DEVICE_POINT_WRITE_COMMAND DEVICE_FILTER
        WHERE DEVICE_FILTER.DELETED = 0
          AND DEVICE_FILTER.DEVICE_ID = #{q.deviceId}
    )


    AND TASK_ID IN (
        SELECT DISTINCT ADDRESS_FILTER.TASK_ID
        FROM T_DEVICE_POINT_WRITE_COMMAND ADDRESS_FILTER
        WHERE ADDRESS_FILTER.DELETED = 0
          AND ADDRESS_FILTER.ADDRESS LIKE '%' || #{q.address} || '%'
    )


    AND CREATE_TIME >= #{q.createTimeFrom}


    AND CREATE_TIME <= #{q.createTimeTo}


    AND EXECUTED_TIME >= #{q.executedTimeFrom}


    AND EXECUTED_TIME <= #{q.executedTimeTo}
